<script setup>import {router} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; const props=defineProps({month:String,summary:Object,recent:Array,links:Object}); const money=v=>new Intl.NumberFormat('es-NI',{style:'currency',currency:'NIO'}).format(Number(v||0));</script>
<template><AppLayout title="Contabilidad" eyebrow="Control financiero" description="Asientos, catálogo y reportes contables."><template #header-actions><a :href="links.createEntry" class="btn-primary">Nuevo asiento</a></template><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><div v-for="item in [['Debe contabilizado',money(summary.debit),'blue'],['Haber contabilizado',money(summary.credit),'emerald'],['Borradores',summary.draft,'gold'],['Reversiones',summary.reversed,'rose']]" :key="item[0]" class="live-metric" :data-tone="item[2]"><p>{{item[0]}}</p><strong>{{item[1]}}</strong></div></section><div class="mt-4 grid gap-4 xl:grid-cols-[1fr_300px]"><section class="card overflow-hidden"><div class="section-heading"><h2 class="font-semibold">Movimientos recientes</h2></div><div class="divide-y"><a v-for="entry in recent" :key="entry.id" :href="`/contabilidad/asientos/${entry.id}`" class="flex justify-between p-4"><div><p class="font-semibold">{{entry.number}} · {{entry.concept}}</p><p class="text-[10px] text-slate-400">{{entry.date}} · {{entry.status}}</p></div><p class="font-semibold">{{money(entry.total_debit)}}</p></a></div></section><aside class="card p-4"><a v-for="item in [['Catálogo de cuentas',links.accounts],['Asientos',links.entries],['Libro diario',links.journal],['Libro mayor',links.ledger],['Balance de comprobación',links.trial]]" :key="item[0]" :href="item[1]" class="block rounded-lg px-3 py-3 text-xs font-semibold hover:bg-blue-50">{{item[0]}} →</a></aside></div></AppLayout></template>
